# ── compact builder helpers ────────────────────────────────────────────────
def _w(id, word, emoji, ctx, dfn, ex, prompt):
    return {'id':id,'word':word,'emoji':emoji,'context':ctx,'definition':dfn,'example':ex,'use_prompt':prompt}

def _i(id, phrase, emoji, literal, meaning, example):
    return {'id':id,'phrase':phrase,'emoji':emoji,'literal':literal,'meaning':meaning,'example':example}

