WORD_TIERS = {'5-7': _T1, '8-10': _T2, '11-13': _T3}
IDIOMS = _IDIOMS

TIER_LABELS = {
    '5-7':  {'label':'Ages 5–7',  'grade':'K–1st Grade',  'emoji':'🟢','color':'#10b981','desc':'Fun action words, feelings, and everyday things'},
    '8-10': {'label':'Ages 8–10','grade':'2nd–4th Grade','emoji':'🟡','color':'#f59e0b','desc':'News words, social words, and descriptive power'},
    '11-13':{'label':'Ages 11–13','grade':'5th–7th Grade','emoji':'🔴','color':'#ef4444','desc':'Article words, debate words, and emotional intelligence'},
}
NEXT_TIER = {'5-7':'8-10','8-10':'11-13','11-13':'11-13'}

BADGES = {
    'first_word':   {'name':'First Word!',   'emoji':'🌱','desc':'Learned your very first word'},
    'day_streak_3': {'name':'3-Day Streak!', 'emoji':'🔥','desc':'Came back 3 days in a row'},
    'day_streak_7': {'name':'Week Warrior!', 'emoji':'🏆','desc':'7 days straight — impressive!'},
    'words_10':     {'name':'Word Collector','emoji':'📚','desc':'Learned 10 words total'},
    'words_25':     {'name':'Vocab Explorer','emoji':'🗺️','desc':'Learned 25 words total'},
    'words_50':     {'name':'Word Master',   'emoji':'🧠','desc':'Learned 50 words total'},
    'words_100':    {'name':'Vocabulary Hero','emoji':'🦸','desc':'100 words learned!'},
    'idiom_5':      {'name':'Phrase Master', 'emoji':'🎭','desc':'Conquered 5 idioms'},
    'idiom_20':     {'name':'Idiom Island Pro','emoji':'🏝️','desc':'Learned 20 idioms!'},
    'challenge':    {'name':'Level Up!',     'emoji':'⬆️','desc':'Completed a challenge word'},
}


def get_daily_words(tier, seen_ids=None):
    if seen_ids is None:
        seen_ids = []
    pool = WORD_TIERS.get(tier, WORD_TIERS['8-10'])
    next_pool = WORD_TIERS.get(NEXT_TIER.get(tier, tier), pool)
    seen_set = set(seen_ids)
    unseen = [w for w in pool if w['id'] not in seen_set]
    seen_words = [w for w in pool if w['id'] in seen_set]
    result = []
    new_word = choice(unseen) if unseen else choice(pool)
    result.append({**new_word, 'word_type': 'new'})
    review_pool = [w for w in seen_words if w['id'] != new_word['id']]
    if not review_pool:
        review_pool = [w for w in pool if w['id'] != new_word['id']]
    if review_pool:
        result.append({**choice(review_pool), 'word_type': 'review'})
    existing_ids = {r['id'] for r in result}
    challenge_pool = [w for w in next_pool if w['id'] not in existing_ids]
    if challenge_pool:
        result.append({**choice(challenge_pool), 'word_type': 'challenge'})
    return result[:3]


def get_daily_idiom(seen_idiom_ids=None):
    if seen_idiom_ids is None:
        seen_idiom_ids = []
    seen_set = set(seen_idiom_ids)
    unseen = [i for i in IDIOMS if i['id'] not in seen_set]
    return choice(unseen) if unseen else choice(IDIOMS)


def compute_new_badges(total_words_seen, streak, total_idioms_seen, earned_badges, has_challenge):
    new_badges = []
    checks = {
        'first_word':   total_words_seen >= 1,
        'day_streak_3': streak >= 3,
        'day_streak_7': streak >= 7,
        'words_10':     total_words_seen >= 10,
        'words_25':     total_words_seen >= 25,
        'words_50':     total_words_seen >= 50,
        'words_100':    total_words_seen >= 100,
        'idiom_5':      total_idioms_seen >= 5,
        'idiom_20':     total_idioms_seen >= 20,
        'challenge':    has_challenge,
    }
    for key, condition in checks.items():
        if condition and key not in earned_badges:
            new_badges.append(key)
    return new_badges
